function barrierCentralized(n){ // mutex + condition variable style
  let waitingTime = 0;
  for(let i=0;i<n;i++){
    // each arrival contends for the single lock
    waitingTime += (i*(n-i))*0.01;
  }
  return waitingTime + 0.2*n + 3;
}

function barrierSenseReversing(n){
  // atomic arrivals + single broadcast flip of sense
  const arrivalsCost = 0.25*n;
  const broadcastOverhead = 2 + 0.1*Math.log(n+1)*n;
  return arrivalsCost + broadcastOverhead;
}

function barrierTree(n,k=4){
  // log_k(n) phases; each phase incurs local fan-in/fan-out
  const phases = Math.log(n+1)/Math.log(k);
  return 0.05*n + 6*phases + 0.08*n*phases;
}

function barrierDissemination(n){
  // pairwise partner exchanges; O(n log n) messaging with low contention
  const L = Math.log(n+1);
  return 0.02*n*L + 1.5*L + 2;
}
